				this.set( binding, map );

			} else if ( binding.isSampledTexture ) {

				const { textureGPU, glTextureType } = this.get( binding.texture );

				map.textureGPU = textureGPU;
				map.glTextureType = glTextureType;

				this.set( binding, map );

