			const gl = this.gl;
			const array = uniformBuffer.buffer;

			uniformBufferData.bufferGPU = gl.createBuffer();

			gl.bindBuffer( gl.UNIFORM_BUFFER, uniformBufferData.bufferGPU );
			gl.bufferData( gl.UNIFORM_BUFFER, array.byteLength, gl.DYNAMIC_DRAW );

